/bin/zsh -lc "python3 -B -c 'import csv,collections,json
from pathlib import Path
p=Path('\\''.'\\'')
mc=list(csv.DictReader(open(p/'\\''data/ModelCondition.csv'\\''))); ss=list(csv.DictReader(open(p/'\\''data/ScreenSequenceMap.csv'\\'')))
print('\\''SIZES'\\'',len(mc),len(ss))
for name,rows in [('\\''MC'\\'',mc),('\\''SS'\\'',ss)]:
 print(name,'\\''columns'\\'',list(rows[0]))
 for k in rows[0]:
  vals=collections.Counter(r[k] for r in rows)
  print(name,k,'\\''nonempty'\\'',sum(n for v,n in vals.items() if v.strip()),'\\''unique'\\'',len(vals),'\\''top'\\'',vals.most_common(12))
ids=collections.Counter(r['\\''ModelConditionID'\\''] for r in mc); lookup={r['\\''ModelConditionID'\\'']:r for r in mc}
print('\\''DUPLICATE_MC_IDS'\\'',[(k,v) for k,v in ids.items() if v>1])
print('\\''MODEL_ID_MISMATCH'\\'',[(i+2,r) for i,r in enumerate(mc) if r['\\''ModelID'\\'']"'!=r['"'\\''model_id'\\'']])
print('\\''PARENTS'\\'')
for i,r in enumerate(mc):
 if r['\\''ParentModelConditionID'\\''].strip():
  print('\\''child_line'\\'',i+2,json.dumps(r),'\\''parent'\\'',json.dumps(lookup.get(r['\\''ParentModelConditionID'\\''].strip())))
print('\\''SS_ORPHANS'\\'',collections.Counter(r['\\''ModelConditionID'\\''] for r in ss if r['\\''ModelConditionID'\\''] not in lookup))
print('\\''SS_MODEL_MISMATCH'\\'',[(i+2,r) for i,r in enumerate(ss) if r['\\''ModelConditionID'\\''] in lookup and r['\\''ModelID'\\'']"'!=lookup[r['"'\\''ModelConditionID'\\'']]['\\''ModelID'\\'']][:30])
print('\\''PASSAGE_ROWS'\\'')
for i,r in enumerate(mc):
 if r['\\''PassageNumber'\\''].strip(): print(i+2,json.dumps(r))
'"

