mc=list(csv.DictReader(open('\\''data/ModelCondition.csv'\\''))); ss=list(csv.DictReader(open('\\''data/ScreenSequenceMap.csv'\\'')))
lookup={r['\\''ModelConditionID'\\'']:r for r in mc}; bymodel=collections.defaultdict(list)
for i,r in enumerate(mc): r['\\''_line'\\'']=i+2; bymodel[r['\\''ModelID'\\'']].append(r)
def key(r):
 return (r['\\''CellFormat'\\''],r['\\''FormulationID'\\'']) if r['\\''CellFormat'\\''].strip().lower() not in ('\\'''\\'','\\''unknown'\\'') and r['\\''FormulationID'\\''].strip() else None
def strict(r): return r['\\''ModelID'\\'']"'!='"'\\''pDNA'\\'' and r['\\''ScreenType'\\'']"'!='"'\\''pDNA'\\'' and all(r[k].strip().lower()==v for k,v in [('\\''PassesQC'\\'','\\''true'\\''),('\\''DrugTreated'\\'','\\''false'\\''),('\\''IsEngineered'\\'','\\''false'\\''),('\\''ExcludeFromCRISPRCombined'\\'','\\''false'\\'')]) and bool(r['\\''Library'\\''].strip())
elig=[r for r in ss if strict(r)]; libs=collections.defaultdict(set); screens=collections.defaultdict(set)
for r in elig: libs[r['\\''ModelConditionID'\\'']].add(r['\\''Library'\\'']); screens[r['\\''ModelConditionID'\\'']].add(r['\\''ScreenID'\\''])
summary=lambda r: {'\\''line'\\'':r['\\''_line'\\''],'\\''id'\\'':r['\\''ModelConditionID'\\''],'\\''source'\\'':r['\\''DataSource'\\''],'\\''key'\\'':key(r),'\\''passage'\\'':r['\\''PassageNumber'\\''],'\\''libraries'\\'':sorted(libs[r['\\''ModelConditionID'\\'']]),'\\''screens'\\'':sorted(screens[r['\\''ModelConditionID'\\'']])}
print('\\''strict_sequences'\\'',len(elig),'\\''strict_screens'\\'',len({r['\\''ScreenID'\\''] for r in elig}),'\\''strict_nodes'\\'',len(libs),'\\''strict_qualified_nodes'\\'',sum(bool(key(lookup[n])) for n in libs))
print('\\''qualification'\\'',collections.Counter('\\''qualified'\\'' if key(r) else '\\''unqualified'\\'' for r in mc))
print('\\''parent_rows'\\'',[(r['\\''_line'\\''],r['\\''ModelConditionID'\\''],r['\\''ParentModelConditionID'\\''],r['\\''AnchorDrug'\\''],key(r),r['\\''ParentModelConditionID'\\''] in lookup,sorted(libs[r['\\''ModelConditionID'\\'']])) for r in mc if r['\\''ParentModelConditionID'\\'']])
print('\\''per_model_counts'\\'',collections.Counter(len(v) for v in bymodel.values()))
print('\\''per_model_qualified_counts'\\'',collections.Counter(sum(bool(key(r)) for r in v) for v in bymodel.values()))
print('\\''models_with_3plus_qualified'\\'')
for m,rows in bymodel.items():
 if sum(bool(key(r)) for r in rows)>=3: print(m,[summary(r) for r in rows])
print('\\''passage_total'\\'',sum(bool(r['\\''PassageNumber'\\'']) for r in mc),'\\''passage_models'\\'',len({r['\\''ModelID'\\''] for r in mc if r['\\''PassageNumber'\\'']}))
print('\\''passage_within_model_count_dist'\\'',collections.Counter(sum(bool(r['\\''PassageNumber'\\'']) for r in rows) for rows in bymodel.values()))
print('\\''passage_multi_distinct_bins'\\'')
for m,rows in bymodel.items():
 prs=[r for r in rows if r['\\''PassageNumber'\\'']]
 if len({r['\\''PassageNumber'\\''] for r in prs})>1: print(m,[summary(r) for r in rows])
print('\\''same_model_key_repeat_plus_other_key'\\'')
for m,rows in bymodel.items():
 keys=collections.Counter(key(r) for r in rows if key(r))
 if len(keys)>=2 and max(keys.values())>=2: print(m,[summary(r) for r in rows])
print('\\''source_vs_qualification'\\'',collections.Counter((r['\\''DataSource'\\''],bool(key(r))) for r in mc))
print('\\''source_vs_strict'\\'',collections.Counter((r['\\''DataSource'\\''],bool(libs[r['\\''ModelConditionID'\\'']])) for r in mc))
print('\\''screens_per_node_dist'\\'',collections.Counter(len(v) for v in screens.values()))
print('\\''same_model_multi_qualified_keys_with_strict'\\'')
for m,rows in bymodel.items():
 q=[r for r in rows if key(r) and libs[r['\\''ModelConditionID'\\'']]]
 if len({key(r) for r in q})>=2: print(m,[summary(r) for r in q])
print('\\''screen_ids_multimap'\\'',[(s,{(r['\\''ModelID'\\''],r['\\''ModelConditionID'\\''],r['\\''Library'\\'']) for r in ss if r['\\''ScreenID'\\'']==s}) for s in {r['\\''ScreenID'\\''] for r in ss if r['\\''ScreenID'\\'']"'!='"'\\''pDNA'\\''} if len({(r['\\''ModelID'\\''],r['\\''ModelConditionID'\\''],r['\\''Library'\\'']) for r in ss if r['\\''ScreenID'\\'']==s})>1])
'"

